COMPONENT = ROOT / "app/components/island3d/LegendarySatelliteIslands.tsx"
LAYOUT = ROOT / "app/(tabs)/_layout.tsx"
QUIZ = ROOT / "app/(tabs)/quiz/[topic].tsx"

DEV_ROUTES = [
    ROOT / "app/(tabs)/devtest.tsx",
    ROOT / "app/(tabs)/devtest_certificate.tsx",
    ROOT / "app/(tabs)/devtest_quizwire.tsx",
]

COMPONENT_SOURCE = base64.b64decode(
    ""
).decode("utf-8")


class PatchError(RuntimeError):
    pass


def read_required(path: Path) -> str:
    if not path.is_file():
        raise PatchError(
            f"Missing required file: {path.relative_to(ROOT)}"
        )
    return path.read_text(encoding="utf-8")


def replace_once(
    text: str,
    old: str,
    new: str,
    label: str,
) -> str:
    if old not in text:
        if new in text:
            return text
        raise PatchError(
            f"Could not locate {label}."
        )
    return text.replace(old, new, 1)


def validate_safe_positions() -> None:
    satellites = {
        "mechaOwl": (8.04, 4.04),
        "chronoFox": (0.53, 8.98),
        "axolotlOracle": (-7.52, 4.95),
        "astralNova": (-8.04, -4.04),
        "celestra": (-0.53, -8.98),
        "aetherwyrm": (7.52, -4.95),
    }

    expansions = {
        "castleReach": (-5.15, -0.70, 2.15 * 1.12),
        "starportDock": (5.00, 1.05, 2.15 * 1.12),
        "crystalWilds": (1.00, -5.00, 2.15 * 1.12),
        "moonTemple": (-0.70, 4.72, 2.15 * 1.14),
    }

    satellite_radius = 0.84
    minimum_clearance = 0.95

    for satellite_name, (x, z) in satellites.items():
        for expansion_name, (
            expansion_x,
            expansion_z,
            expansion_radius,
        ) in expansions.items():
            center_distance = math.hypot(
                x - expansion_x,
                z - expansion_z,
            )

            clearance = center_distance - (
                satellite_radius +
                expansion_radius
            )

            if clearance < minimum_clearance:
                raise PatchError(
                    "Unsafe legendary placement: "
                    f"{satellite_name} is only "
                    f"{clearance:.2f} units from "
                    f"{expansion_name}."
                )


