def patch_layout(text: str) -> str:
    text, _ = re.subn(
        r"\n// --------------------\n"
        r"// DEV-ONLY imports\n"
        r"// --------------------\n"
        r"if \(__DEV__\) \{[\s\S]*?\n\}\n",
        "\n",
        text,
        count=1,
    )
    return text


def patch_quiz(text: str) -> str:
    text = re.sub(
        r"\n// 🔧 Dev-only UI\.[^\n]*\n"
        r"const SHOW_DEV_QUIZ_CHEAT = __DEV__;\n",
        "\n",
        text,
        count=1,
    )

    text, _ = re.subn(
        r"\n  // DEV helper: force quiz to finish with target %[\s\S]*?"
        r"\n  async function onPick",
        "\n  async function onPick",
        text,
        count=1,
    )

    text, _ = re.subn(
        r"\n\s*\{SHOW_DEV_QUIZ_CHEAT && \([\s\S]*?"
        r"\n\s*\)\}\n",
        "\n",
        text,
        count=1,
    )

    style_start = text.find(
        "  devRow: {"
    )
    style_end = text.find(
        "\n});",
        style_start,
    )

    if style_start >= 0 and style_end > style_start:
        text = (
            text[:style_start]
            + text[style_end:]
        )

    return text


def syntax_check(
    files: dict[Path, str]
) -> None:
    node_script = r"""
const fs = require("fs");
const ts = require("typescript");
let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");

  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (diagnostic) =>
      diagnostic.category ===
      ts.DiagnosticCategory.Error
  );

  if (errors.length) {
    failed = true;
    console.error(`Syntax errors in ${file}:`);

    for (const error of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(
          error.messageText,
          "\\n"
        )
      );
    }
  }
}

process.exit(failed ? 1 : 0);
"""

    with tempfile.TemporaryDirectory(
        prefix="nova-clickable-legendaries-"
    ) as temp:
        temp_root = Path(temp)
        temp_files: list[str] = []

        for index, (
            path,
            content,
        ) in enumerate(files.items()):
            target = (
                temp_root
                / f"{index}-{path.name}"
            )
            target.write_text(
                content,
                encoding="utf-8",
            )
            temp_files.append(str(target))

        result = subprocess.run(
            [
                "node",
                "-e",
                node_script,
                *temp_files,
            ],
            cwd=ROOT,
            text=True,
            capture_output=True,
        )

        if result.returncode != 0:
            raise PatchError(
                result.stderr.strip()
                or result.stdout.strip()
            )


def make_backup(
    paths: list[Path]
) -> Path:
    stamp = datetime.now().strftime(
        "%Y%m%d-%H%M%S"
    )

    backup_dir = ROOT / "backups"
    backup_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    backup = (
        backup_dir
        / f"before_clickable_legendary_islands_{stamp}.zip"
    )

    with zipfile.ZipFile(
        backup,
        "w",
        zipfile.ZIP_DEFLATED,
    ) as archive:
        for path in paths:
            if path.is_file():
                archive.write(
                    path,
                    path.relative_to(ROOT),
                )

    return backup


def main() -> int:
    try:
        validate_safe_positions()

        scene_original = read_required(
            SCENE
        )

        if (
            "LegendarySatelliteIslands"
            not in scene_original
        ):
            raise PatchError(
                "The first legendary-island installer "
                "has not been applied yet."
            )

        scene = patch_scene(
            scene_original
        )

        updated: dict[Path, str] = {
            SCENE: scene,
            COMPONENT: COMPONENT_SOURCE,
        }

        if LAYOUT.is_file():
            updated[LAYOUT] = patch_layout(
                LAYOUT.read_text(
                    encoding="utf-8"
                )
            )

        if QUIZ.is_file():
            updated[QUIZ] = patch_quiz(
                QUIZ.read_text(
                    encoding="utf-8"
                )
            )

        syntax_check(updated)

        backup = make_backup(
            [
                SCENE,
                COMPONENT,
                LAYOUT,
                QUIZ,
                *DEV_ROUTES,
            ]
        )

        COMPONENT.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        for path, content in updated.items():
            path.write_text(
                content,
                encoding="utf-8",
            )

        removed: list[str] = []

        for route in DEV_ROUTES:
            if route.is_file():
                route.unlink()
                removed.append(
                    str(
                        route.relative_to(ROOT)
                    )
                )

        print(
            "✅ Legendary landmarks are now clickable."
        )
        print(
            "✅ Tapping one zooms the camera to it."
        )
        print(
            "✅ The Island information card shows its title and description."
        )
        print(
            "✅ Moved all six to the safe rotated 9-unit orbit."
        )
        print(
            "✅ Validated clearance from all four future Island expansions."
        )
        print(
            "✅ Dev-test routes and quiz cheat remain removed."
        )
        print(
            "✅ Syntax check passed for every changed file."
        )
        print(
            f"✅ Backup: {backup.relative_to(ROOT)}"
        )

        if removed:
            print("Removed remaining dev routes:")
            for item in removed:
                print(f"  - {item}")

        print(
            "\nNext command: npx expo start -c"
        )

        return 0

    except PatchError as error:
        print("❌ Nothing was written.")
        print(f"Reason: {error}")
        return 1
    except Exception as error:
        print("❌ Nothing was written.")
        print(
            "Unexpected error: "
            f"{type(error).__name__}: {error}"
        )
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
